Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include <cstdio>
#include <queue>
#include <vector>
#include <cstring>
#include <algorithm>
#include <utility>
using namespace std;

typedef pair<int,int> pii;

const int MAXN = 300;

vector<int> adj[MAXN];
vector<int> to, rev, cap;

void add_edge(int u, int v, int c) {
    int a = (int)to.size();
    to.push_back(v);
    cap.push_back(c);
    rev.push_back((int)adj[v].size());

    int b = (int)to.size();
    to.push_back(u);
    cap.push_back(0);
    rev.push_back((int)adj[u].size());

    adj[u].push_back(a);
    adj[v].push_back(b);
}

int levelArr[MAXN], itArr[MAXN];

bool bfs(int s, int t) {
    memset(levelArr, -1, sizeof(levelArr));
    queue<int> q;
    levelArr[s] = 0;
    q.push(s);
    while (!q.empty()) {
        int v = q.front(); q.pop();
        for (int e : adj[v]) {
            if (cap[e] > 0 && levelArr[to[e]] == -1) {
                levelArr[to[e]] = levelArr[v] + 1;
                q.push(to[e]);
            }
        }
    }
    return levelArr[t] != -1;
}

int dfs(int v, int t, int f) {
    if (v == t) return f;
    for (int &i = itArr[v]; i < (int)adj[v].size(); ++i) {
        int e = adj[v][i];
        if (cap[e] > 0 && levelArr[v] + 1 == levelArr[to[e]]) {
            int pushed = dfs(to[e], t, min(f, cap[e]));
            if (pushed) {
                cap[e] -= pushed;
                cap[rev[e]] += pushed;
                return pushed;
            }
        }
    }
    return 0;
}

int maxflow(int s, int t) {
    int flow = 0;
    while (bfs(s, t)) {
        memset(itArr, 0, sizeof(itArr));
        while (true) {
            int pushed = dfs(s, t, 1 << 30);
            if (!pushed) break;
            flow += pushed;
        }
    }
    return flow;
}

int n, t;
int S, T;
int rp, cp;
int in;
int srcId[21][21], sinkId[21][21];
int mark[21][21], dist[21][21];
char grid[21][21], grid2[21][21];
int dr[4] = {-1, 0, 1, 0};
int dc[4] = {0, 1, 0, -1};

bool valid(int r, int c) {
    return r >= 0 && r < n && c >= 0 && c < n;
}

void searchEdges(int a, int b) {
    queue<pii> q;
    memset(mark, 0, sizeof(mark));
    memset(dist, -1, sizeof(dist));
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (grid[i][j] == 'Y') mark[i][j] = 1;

    q.push(make_pair(rp, cp));
    q.push(make_pair(a, b));
    dist[a][b] = dist[rp][cp] = 0;
    mark[a][b] = 1;
    mark[rp][cp] = 2;

    while (!q.empty()) {
        pii now = q.front(); q.pop();
        int r = now.first, c = now.second;
        if (mark[r][c] == 1 && grid2[r][c] > '0' && grid2[r][c] <= '9')
            add_edge(srcId[a][b], sinkId[r][c], 9);

        if (mark[r][c] == 1 && dist[r][c] == t) continue;

        for (int k = 0; k < 4; ++k) {
            int nr = r + dr[k], nc = c + dc[k];
            if (valid(nr, nc) && mark[nr][nc] == 0) {
                mark[nr][nc] = mark[r][c];
                dist[nr][nc] = dist[r][c] + 1;
                q.push(make_pair(nr, nc));
            } else if (mark[r][c] == 1 && valid(nr, nc) && mark[nr][nc] == 2 && dist[nr][nc] == dist[r][c] + 1 && grid2[nr][nc] > '0' && grid2[nr][nc] <= '9') {
                add_edge(srcId[a][b], sinkId[nr][nc], 9);
            }
        }
    }
}

int main() {
    if (scanf("%d %d", &n, &t) != 2) return 0;
    S = 202; T = 203;
    in = 0;
    memset(srcId, -1, sizeof(srcId));
    memset(sinkId, -1, sizeof(sinkId));

    for (int i = 0; i < n; ++i) {
        scanf("%s", grid[i]);
        for (int j = 0; j < n; ++j) {
            if (grid[i][j] > '0' && grid[i][j] <= '9') {
                add_edge(S, in, grid[i][j] - '0');
                srcId[i][j] = in++;
            }
            if (grid[i][j] == 'Z') {
                rp = i; cp = j;
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        scanf("%s", grid2[i]);
        for (int j = 0; j < n; ++j) {
            if (grid2[i][j] > '0' && grid2[i][j] <= '9') {
                add_edge(in, T, grid2[i][j] - '0');
                sinkId[i][j] = in++;
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (grid[i][j] > '0' && grid[i][j] <= '9' && grid2[i][j] > '0' && grid2[i][j] <= '9')
                add_edge(srcId[i][j], sinkId[i][j], 9);
            if (grid[i][j] > '0' && grid[i][j] <= '9')
                searchEdges(i, j);
        }
    }

    printf("%d\n", maxflow(S, T));
    return 0;
}
